using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using Petrichor.Core;using Windows.UI.Xaml;using Windows.UI.Xaml.Controls;using Windows.UI.Xaml.Navigation;using Windows.Storage;namespace Petrichor.App.Pages {public sealed partial class LoginPage : MusicPage {public LoginPage(){InitializeComponent();}
private CancellationTokenSource polling;public bool HasQr=>QrImage.Source!=null;
protected override Task LoadAsync(object p)=>RefreshAsync();
public static byte[] CreateQr(string url){using(var generator=new QRCoder.QRCodeGenerator())using(var data=generator.CreateQrCode(url,QRCoder.QRCodeGenerator.ECCLevel.M))using(var code=new QRCoder.PngByteQRCode(data))return code.GetGraphic(8);}
private async Task RefreshAsync(){polling?.Cancel();polling=CancellationTokenSource.CreateLinkedTokenSource(Token);var ct=polling.Token;Status.Text="正在生成二维码…";QrImage.Source=null;var challenge=await App.Api.BeginQrLoginAsync(ct);var bytes=CreateQr(challenge.LoginUrl.ToString());using(var stream=new Windows.Storage.Streams.InMemoryRandomAccessStream()){using(var writer=new Windows.Storage.Streams.DataWriter(stream.GetOutputStreamAt(0))){writer.WriteBytes(bytes);await writer.StoreAsync();}stream.Seek(0);var bitmap=new Windows.UI.Xaml.Media.Imaging.BitmapImage();await bitmap.SetSourceAsync(stream);QrImage.Source=bitmap;}Status.Text="等待扫码";PollAsync(challenge,ct);}
private async void PollAsync(QrLoginChallenge challenge,CancellationToken ct){try{var progress=new Progress<QrLoginState>(state=>{if(ct.IsCancellationRequested||!IsCurrent)return;Status.Text=state==QrLoginState.Scanned?"已扫码，请在手机上确认":state==QrLoginState.Expired?"二维码已过期，请刷新":"等待扫码";});await App.Api.WaitForQrLoginAsync(challenge,progress,ct);if(!ct.IsCancellationRequested&&IsCurrent){Status.Text="登录成功";App.NotifyAccountChanged();Shell.Current.Navigate(typeof(LibraryPage));}}catch(OperationCanceledException){}catch(MusicApiException e){if(IsCurrent&&!ct.IsCancellationRequested)Status.Text=e.Code==800 ? "二维码已过期，请刷新" : UserMessages.For(e);}catch(Exception e){if(IsCurrent&&!ct.IsCancellationRequested)Status.Text="登录暂时不可用，请刷新重试。";await App.LogAsync(e);}}
private async void RefreshClick(object s,RoutedEventArgs e)=>await ExecuteAsync(RefreshAsync);
protected override void OnNavigatedFrom(NavigationEventArgs e){polling?.Cancel();base.OnNavigatedFrom(e);}}}

